-- E0 ONLY (sandbox): meta.source_object and the schema snapshot tables as read
-- from dwh on 04.11.2026 (i04_step2_snapshot_structure.sql), so that 006 can be
-- tested in an empty PostgreSQL. Never run against dwh or a copy of it.
CREATE TABLE IF NOT EXISTS meta.source_object (
  source_object_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  source_system_id bigint NOT NULL REFERENCES meta.source_system(source_system_id),
  source_schema varchar(100) NOT NULL, source_object varchar(200) NOT NULL,
  object_type varchar(50) NOT NULL DEFAULT 'TABLE', is_active boolean NOT NULL DEFAULT true);
CREATE TABLE meta.metadata_capture (
  metadata_capture_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  source_system_id bigint NOT NULL CONSTRAINT fk_metadata_capture_source_system REFERENCES meta.source_system(source_system_id),
  status varchar(20) NOT NULL CONSTRAINT ck_metadata_capture_status CHECK (status IN ('RUNNING', 'SUCCESS', 'FAILED')),
  started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz,
  source_database varchar(200), source_version varchar(200),
  objects_captured integer NOT NULL DEFAULT 0, columns_captured integer NOT NULL DEFAULT 0,
  created_by varchar(100) NOT NULL DEFAULT 'metadata_capture', message text);
CREATE TABLE meta.source_object_snapshot (
  object_snapshot_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  metadata_capture_id bigint NOT NULL CONSTRAINT fk_object_snapshot_capture REFERENCES meta.metadata_capture(metadata_capture_id),
  source_object_id bigint NOT NULL CONSTRAINT fk_object_snapshot_source_object REFERENCES meta.source_object(source_object_id),
  source_schema varchar(100) NOT NULL, source_object varchar(200) NOT NULL,
  relkind varchar(10) NOT NULL, object_type varchar(50) NOT NULL,
  captured_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_object_snapshot UNIQUE (metadata_capture_id, source_object_id));
CREATE TABLE meta.source_column_snapshot (
  column_snapshot_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  object_snapshot_id bigint NOT NULL CONSTRAINT fk_column_snapshot_object REFERENCES meta.source_object_snapshot(object_snapshot_id),
  ordinal_position integer NOT NULL, column_name varchar(200) NOT NULL, formatted_type text NOT NULL,
  udt_name varchar(200) NOT NULL, is_nullable boolean NOT NULL,
  is_primary_key boolean NOT NULL DEFAULT false, is_unique_key boolean NOT NULL DEFAULT false,
  is_identity boolean NOT NULL DEFAULT false, is_generated boolean NOT NULL DEFAULT false,
  default_expression text, column_comment text, captured_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_column_snapshot_name UNIQUE (object_snapshot_id, column_name),
  CONSTRAINT uq_column_snapshot_position UNIQUE (object_snapshot_id, ordinal_position));
GRANT SELECT ON meta.metadata_capture, meta.source_object_snapshot, meta.source_column_snapshot TO dwh_app;

-- I04 package 007: schema etl and the ETL role (cluster role created once in the sandbox).
CREATE SCHEMA IF NOT EXISTS etl;
DO $r$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'dwh_etl') THEN CREATE ROLE dwh_etl LOGIN; END IF;
END $r$;
GRANT USAGE ON SCHEMA etl TO dwh_etl;

-- I05 package 008: legacy catalogs (only the columns 008 reads), as read from dwh on 04.11.2026.
CREATE TABLE IF NOT EXISTS meta.column_contract (contract_id bigint PRIMARY KEY, source_system_code varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS meta.mapping_rule (mapping_id bigint PRIMARY KEY, source_system_code varchar(100) NOT NULL);
CREATE SCHEMA IF NOT EXISTS stg;
CREATE SCHEMA IF NOT EXISTS ods;
